const CHHAU_INFO={id:"chhau-masks",title:"Chhau Mask Heritage & Performance Art",originRegion:"Purulia (West Bengal), Seraikela (Jharkhand), Mayurbhanj (Odisha)",unescoStatus:"UNESCO Intangible Cultural Heritage of Humanity",community:"Sutradhar Artisan Guilds & Chhau Dancers",materials:"Paper-Mache, Clay, Gauze Cloth, Jute, Acrylic Colors, Feathers",danceStyle:"Martial Folk Dance depicting Ramayana & Mahabharata",quickStats:[{label:"UNESCO Listed",value:"Intangible Heritage",icon:"🏛️"},{label:"Artisan Village",value:"Charida, Purulia",icon:"📍"},{label:"Base Medium",value:"Papier-Mâché & Clay",icon:"🎨"},{label:"Performance",value:"Martial Folk Dance",icon:"🎭"},{label:"Themes",value:"Epics & Puranas",icon:"📜"},{label:"Headgear",value:"Zari & Feathers",icon:"🪶"}]},PROCESS_STEPS=[{step:1,title:"Clay Model Sculpting",description:"Artisans sculpt a detailed clay model (mati ghoro) of the specific deity, demon, or animal character on a wooden board."},{step:2,title:"Papier-Mache & Cloth Layering",description:"Layers of soft paper strips dipped in water-gUM paste are pasted onto the clay model, followed by fine gauze cloth for structural durability."},{step:3,title:"Drying & Clay Shell Removal",description:"The molded mask is sun-dried, after which the inner clay core is carved out, leaving a lightweight, hollow paper-mache shell."},{step:4,title:"Sanding & Vibrant Painting",description:"The surface is coated with zinc white base (khari) and hand-painted in vivid colors: yellow/orange for gods (Deva), red/black for demons (Asura)."},{step:5,title:"Crown & Feather Embellishment",description:"Elaborate mukut (crowns) decorated with peacock feathers, tinsel, beads, zari threads, and artificial flowers are attached to top of the mask."}],TRADITIONAL_MASKS=[{name:"Deva (Divine Gods & Heroes)",description:"Heroic, serene masks painted in golden-yellow or flesh tones representing Rama, Krishna, Durga, and Shiva."},{name:"Asura (Demons & Villains)",description:"Ferocious, menacing masks painted dark red or green with protruding fangs, bushy eyebrows, and demon horns representing Ravana and Mahishasura."},{name:"Pashu (Animals & Mythical Beasts)",description:"Expressive animal masks including lions, tigers, stags, and monkeys used in naturalistic tribal hunt dances."},{name:"Kirtimukha (Glory Face Shields)",description:"Decorative mask crowns used as symbolic protective guardians above temple doors and stage entrances."}],ARTISAN_COMMUNITY={title:"Charida Village — Mask Makers of Purulia",description:"Located at the foot of Ajodhya Hills in Purulia district, Charida is a dedicated craft village where over 300 Sutradhar artisan families have hand-crafted Chhau masks for over 150 years."},GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Purulia_Chhau_dance_mask.jpg/800px-Purulia_Chhau_dance_mask.jpg",caption:"Purulia Chhau Mask depicting Goddess Durga with elaborate peacock feather crown",category:"Mask Art"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Chhau_dance_performance.jpg/800px-Chhau_dance_performance.jpg",caption:"Chhau folk dance troupe performing epic martial acrobatics in full costume",category:"Performance"}],REFERENCES=[{text:"UNESCO Intangible Cultural Heritage — Chhau Dance Inscription.",link:"https://ich.unesco.org"},{text:"West Bengal Khadi and Village Industries Board — Purulia Chhau Mask Documentation.",link:"#"},{text:"Bhattacharyya, Asutosh (1972). Chhau Dance of Purulia. Rabindra Bharati University.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={CHHAU_INFO:CHHAU_INFO,PROCESS_STEPS:PROCESS_STEPS,TRADITIONAL_MASKS:TRADITIONAL_MASKS,ARTISAN_COMMUNITY:ARTISAN_COMMUNITY,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});